import {config,pending} from './lib/config.js';
import {getRound,qualifies,inReward,timer,when,demoAnchor} from './lib/rounds.js';
import {DemoWalletProvider,DemoBalanceProvider,DemoRegistrationProvider,DemoResultsProvider,DemoPayoutProvider,demoAddress} from './lib/providers.js';
const $=s=>document.querySelector(s),wallet=new DemoWalletProvider(),balances=new DemoBalanceProvider(),registration=new DemoRegistrationProvider(),results=new DemoResultsProvider(),payouts=new DemoPayoutProvider(),anchor=demoAnchor(Date.now());
let offset=anchor+86400000-2538000-Date.now(),address=null,balance=null,mode='disconnected',rows=[],all=false,checking=false,registering=false,error='',round=getRound(Date.now()+offset,anchor),lastId=round.id,board='loading',loadId=0;
const now=()=>Date.now()+offset,short=a=>a.slice(0,6)+'…'+a.slice(-4),eth=w=>(Number(w/10n**12n)/1e6).toFixed(4),pct=v=>(Number(v)/1e6).toFixed(v%10000n?6:2),toast=t=>{$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',4000);};
function renderTable(){if(board!=='ready'){$('#table').innerHTML='<div class="empty">'+(board==='loading'?'Loading leaderboard…':'Leaderboard unavailable. <button id="retry" class="outline">Retry</button>')+'</div>';$('#retry')?.addEventListener('click',()=>{mode='open';loadRows();});return;}const q=$('#search').value.trim().toLowerCase();let filtered=rows.map((r,i)=>({...r,rank:i+1})).filter(r=>r.address.includes(q));if(!all)filtered=filtered.slice(0,8);$('#table').innerHTML=filtered.length?'<table><thead><tr><th>#</th><th>TRADER</th><th class="equity">START / ETH</th><th class="equity">CURRENT / ETH</th><th>RETURN</th><th>POSITION</th></tr></thead><tbody>'+filtered.map(r=>`<tr class="${r.address===address?'me':''}"><td>${String(r.rank).padStart(2,'0')}</td><td title="${r.address}"><span class="trader-avatar">${r.rank<4?'✦':'⌁'}</span>${short(r.address)}${r.address===address?' · You':''}</td><td class="equity">${eth(r.start)}</td><td class="equity">${eth(r.current)}</td><td class="${r.ret>0?'return':'below'}">${r.ret>=0?'+':''}${pct(r.ret)}%</td><td class="qual ${!qualifies(r.ret)?'below':r.rank>10?'outside':''}">${inReward(r.ret,r.rank)?'↗ In reward position':qualifies(r.ret)?'↗ Outside top 10':'— Below threshold'}</td></tr>`).join('')+'</tbody></table>':'<div class="empty">'+(q?'No wallets match your search.':'No participants yet.')+'</div>';$('#show-all').textContent=all?'Show top 8 ↑':`View all ${rows.length} traders ↓`;}
async function loadRows(){const id=++loadId;board='loading';renderTable();try{const data=await results.leaderboard(mode);if(id!==loadId)return;rows=data;board='ready';$('#qualified').parentElement.innerHTML=rows.length+' <small id="qualified">/ '+rows.filter(r=>qualifies(r.ret)).length+' above +50%</small>';$('#updated').textContent='Updated '+new Date().toLocaleTimeString('en-US',{hour:'2-digit',minute:'2-digit'});}catch{if(id!==loadId)return;board='error';}renderTable();addMobileEquity();renderEntry();}
function addMobileEquity(){document.querySelectorAll('#table tbody tr').forEach(tr=>{const cells=tr.querySelectorAll('td');if(cells.length===6&&!cells[1].querySelector('.mobile-equity')){const detail=document.createElement('span');detail.className='mobile-equity';detail.textContent=cells[2].textContent+' → '+cells[3].textContent+' ETH';detail.title='Starting equity → Current equity';cells[1].append(detail);}});}
function renderEntry(){const me=rows.find(r=>r.address===address),registered=registration.has(address,round.nextId),participating=!!address&&(!!me||registration.has(address,round.id));$('#connect').innerHTML=address?short(address)+' <span>×</span>':'Connect wallet <span>↗</span>';$('#entry-title').innerHTML=participating?'Make your<br>move.':registered?'You’re on<br>the list.':address?'Your next<br>summit.':'Your place is<br>waiting.';let html='';if(participating){const rank=rows.indexOf(me)+1;html+=me?`<div class="stats"><div><span>CURRENT RANK</span><b>#${rank}</b></div><div><span>RETURN</span><b class="return">+${pct(me.ret)}%</b></div><div><span>STARTING / ETH</span><b>${eth(me.start)}</b></div><div><span>CURRENT / ETH</span><b>${eth(me.current)}</b></div></div><p>${qualifies(me.ret)?'Above +50%':me.ret===50000000n?'Exactly +50% does not qualify':'Below the +50% threshold'} · ${rank<=10?'In top 10':'Outside top 10'}. Live positions are not final.</p>`:'<p>Participating in current round. Trading data is pending.</p>';}if(!address)html+='<p>Connect your wallet to check eligibility and enter the next round.</p><button id="entry-connect" class="primary">Connect wallet ↗</button>';else if(registered)html+=`<p class="return">✓ Registered for next round #${round.nextId}. Demo entry confirmed.</p><p>Starts ${when(round.end)}. Register separately for every round.</p>`;else if(balance!==null)html+=`<p>✓ Eligibility confirmed<br>Your balance: ${(balance/10n**18n).toLocaleString('en-US')} TOKEN</p><button id="join" class="primary" ${!round.entryOpen||registering?'disabled':''}>${registering?'Registration pending…':round.entryOpen?'Join next round ↗':'Registration not open'}</button>`;else html+='<p>Required: 10,000,000 TOKEN.'+(mode==='insufficient'?'<br>Your balance: 7,250,000 TOKEN.<br>Missing: 2,750,000 TOKEN.':'<br>Check your balance before registering.')+'</p><button id="check" class="primary" '+(checking?'disabled':'')+'>'+(checking?'Checking balance…':'Check eligibility ↗')+'</button>';if(error)html+='<p role="alert" class="outside">'+error+'</p>';if(mode==='network')html+='<button id="switch" class="outline">Switch demo network</button>';$('#entry-content').innerHTML=html;$('#entry-connect')?.addEventListener('click',()=>$('#wallet-dialog').showModal());$('#check')?.addEventListener('click',check);$('#join')?.addEventListener('click',join);$('#switch')?.addEventListener('click',()=>{mode='open';error='';renderEntry();});}
async function connect(){try{address=await wallet.connect(mode);balance=null;error='';$('#wallet-dialog').close();renderEntry();renderTable();return{address,demo:true};}catch(e){toast(e.message);return{error:e.message};}}
async function check(){checking=true;error='';renderEntry();try{const b=await balances.check(address,mode);if(b<config.required*10n**18n){balance=null;error='Insufficient token balance.';}else balance=b;}catch(e){error=e.message;}checking=false;renderEntry();return{eligible:balance!==null,error};}
async function join(){if(registering)return;registering=true;error='';renderEntry();try{const r=await registration.register({address,id:round.nextId,now,anchor,balance:balance??0n});toast('Demo registration confirmed for round #'+r.id);}catch(e){error=e.message;}registering=false;renderEntry();return{registered:registration.has(address,round.nextId),roundId:round.nextId,error};}
function tick(){round=getRound(now(),anchor);if(lastId!==round.id){lastId=round.id;mode='open';rows=[];loadRows();renderHistory(true);renderEntry();toast('New round started. Previous results pending verification.');}$('#timer').textContent=timer(round.end-now());$('#round-number').textContent='#'+String(round.id).padStart(3,'0');$('#round-status').textContent='● LIVE ROUND';$('#round-dates').textContent=when(round.start);$('#next-label').textContent='NEXT ROUND #'+String(round.nextId).padStart(3,'0');$('#next-status').textContent=round.entryOpen?'Registration open':'Registration not open';$('#next-start').textContent=(round.entryOpen?'Starts ':'Entry opens '+when(round.end-config.windowMs)+'. Starts ')+when(round.end)+'. Provisional schedule.';const disabled=$('#join')?.disabled;if(disabled!==undefined&&!registering&&disabled===round.entryOpen)renderEntry();}
const scenarios={disconnected:'Wallet disconnected',insufficient:'Insufficient tokens',early:'Eligible · registration not open',open:'Registration open',registered:'Registered for next round',below:'Participating · below threshold',top:'Participating · top 10',outside:'Participating · outside top 10',exact:'Exactly +50% · not qualified',rollover:'Round ends in 5 seconds',pending:'Results pending',finalized:'Finalized · ten winners',network:'Unsupported network','connection-error':'Wallet connection error','verification-error':'Balance verification error','leaderboard-error':'Leaderboard error',empty:'No participants'};
async function setScenario(value){if(!config.demo||!Object.hasOwn(scenarios,value))throw Error('Unknown demo scenario');mode=value;registration.clear();balance=null;error='';address=['disconnected','connection-error'].includes(value)?null:demoAddress;offset=anchor+config.roundMs-(value==='early'?7200000:value==='rollover'?5000:2538000)-Date.now();round=getRound(now(),anchor);lastId=round.id;if(!['disconnected','insufficient','network','connection-error','verification-error'].includes(value))balance=12500000n*10n**18n;if(value==='registered')await registration.register({address,id:round.nextId,now,anchor,balance});$('#scenario').value=value;tick();await loadRows();renderHistory(value==='pending');renderEntry();if(value==='pending'||value==='finalized')$('#history').scrollIntoView({behavior:'smooth'});return{scenario:value,demo:true};}
function renderHistory(isPending=false){$('#history-list').innerHTML=(isPending?'<div class="history-row"><div><h3>Round #'+(round.id-1)+'</h3><p>Trading ended · Results pending verification</p></div><span class="demo">Not paid</span></div>':'')+payouts.history(anchor).filter(r=>!isPending||r.id!==round.id-1).map(r=>`<div class="history-row"><div><h3>Round #${r.id}</h3><p>${new Date(r.start).toLocaleDateString('en-US',{month:'short',day:'numeric'})} – ${new Date(r.end).toLocaleDateString('en-US',{month:'short',day:'numeric'})} · ${r.participants} traders</p></div><div><strong>${eth(r.pool)} ETH</strong><p>Final demo pool</p></div><div><span class="return">10 equal shares</span><p>Finalized · Not paid</p></div><button class="outline history-button" data-id="${r.id}" aria-expanded="false">View results ↗</button></div><div class="history-detail" id="history-${r.id}" hidden><p class="muted">Each winner: 10% · ${eth(r.pool/10n)} ETH. Demo allocation. No payment has occurred.</p><table><thead><tr><th>TRADER</th><th>RETURN</th><th>SHARE</th></tr></thead><tbody>${r.winners.map(w=>`<tr><td>${w.address}</td><td class="return">+${w.ret.toFixed(2)}%</td><td>10%</td></tr>`).join('')}</tbody></table></div>`).join('');document.querySelectorAll('.history-button').forEach(b=>b.onclick=()=>{const el=$('#history-'+b.dataset.id);el.hidden=!el.hidden;b.setAttribute('aria-expanded',String(!el.hidden));b.textContent=el.hidden?'View results ↗':'Hide results ↑';});}
$('#connect').onclick=()=>{if(address){address=null;balance=null;renderEntry();renderTable();}else $('#wallet-dialog').showModal();};$('#close-dialog').onclick=()=>$('#wallet-dialog').close();$('#demo-connect').onclick=connect;$('#show-all').onclick=()=>{all=!all;renderTable();};$('#search').oninput=renderTable;$('#scenario').innerHTML=Object.entries(scenarios).map(([k,v])=>`<option value="${k}">${v}</option>`).join('');$('#scenario').onchange=e=>setScenario(e.target.value);$('#pending-rules').textContent=pending.join(' · ')+'. Pending confirmation. Demo starts at provisional 12:00 America/New_York, then advances in exact 24-hour intervals. Fixed daily ET time conflicts with daylight-saving changes; production policy must be confirmed.';
$('#faq').innerHTML=Object.entries({'When can I join?':'Registration opens in the final hour of the current round. Check your 10M TOKEN balance, then register separately for the next round.','Can I join a round after it starts?':'No. All participants start together. Registration closes at the start.','Does +50% qualify?':'No. Unrounded trading return must be strictly above +50%. Exactly +50% does not qualify.','How are winners ranked?':'By trading return in ETH, descending, after verification. At most ten participants above +50% qualify. Tie-breaking is pending confirmation.','Do higher places earn a bigger share?':'No. Ten winners each receive 10%. Distribution with fewer than ten winners is pending confirmation.','Can I enter the next round while the current one is live?':'Yes, in its final hour. Current trading continues. Registration does not automatically carry over.','How is trading return measured?':'A provider must value eligible positions in ETH and exclude external deposits and withdrawals. This demo uses simulated results, not raw ETH-balance comparisons.'}).map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('');
tick();renderEntry();renderHistory();loadRows();setInterval(tick,1000);
if(document.modelContext?.registerTool){for(const tool of [{name:'read_arena',description:'Read the current demo round and registration.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({roundId:round.id,entryOpen:round.entryOpen,connected:!!address,registered:registration.has(address,round.nextId),demo:true})},{name:'set_demo_scenario',description:'Change the visible local participation simulation. No real transactions.',inputSchema:{type:'object',properties:{scenario:{type:'string',enum:Object.keys(scenarios)}},required:['scenario'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>setScenario(input.scenario)}]){try{Promise.resolve(document.modelContext.registerTool(tool)).catch(()=>{});}catch{}}}

